<script setup lang="ts">
import { computed, onUnmounted, ref } from 'vue';
import { ElButton } from 'element-plus';
const props=defineProps<{shots:{id:number;text:string;seconds:number;overlap?:number;referenceImage?:string;references?:{id:number;dataUrl:string}[];referenceId?:number}[]}>();
const elapsed=ref(0);const playing=ref(false);const narration=ref(false);
const total=computed(()=>props.shots.reduce((n,s,i)=>n+s.seconds-(i<props.shots.length-1?(s.overlap??0):0),0));
const current=computed(()=>{let end=0;return props.shots.find(s=>{end+=s.seconds-(s!==props.shots.at(-1)?(s.overlap??0):0);return elapsed.value<end;})||props.shots.at(-1);});
let lastId:number|undefined;
function stopVoice(){if('speechSynthesis' in window)window.speechSynthesis.cancel();}
function toggle(){playing.value=!playing.value;if(!playing.value)stopVoice();}
const timer=setInterval(()=>{if(!playing.value)return;elapsed.value+=0.1;if(elapsed.value>=total.value){playing.value=false;elapsed.value=0;stopVoice();lastId=undefined;return;}if(current.value?.id!==lastId){lastId=current.value?.id;if(narration.value&&current.value&&'speechSynthesis' in window){stopVoice();const utterance=new SpeechSynthesisUtterance(current.value.text);utterance.lang='zh-CN';window.speechSynthesis.speak(utterance);}}},100);
onUnmounted(()=>{clearInterval(timer);stopVoice();});
</script>
<template><section class="player"><div class="screen"><img v-if="current?.referenceImage || current?.references?.find(r=>r.id===current?.referenceId)" :src="current?.referenceImage || current?.references?.find(r=>r.id===current?.referenceId)?.dataUrl" alt="当前镜头参考图" style="width:100%;height:350px;object-fit:contain"/><svg v-else viewBox="0 0 640 300" role="img" aria-label="程序绘制的分镜构图示意"><defs><linearGradient id="stage-gradient"><stop stop-color="#222b59"/><stop offset="1" stop-color="#7067b7"/></linearGradient></defs><rect width="640" height="300" fill="url(#stage-gradient)"/><g :style="{transform:`translate(${Math.sin(elapsed)*12}px,0)`}"><circle cx="320" cy="135" r="62" fill="#b3b8f0" opacity=".25"/><path d="M230 210 L290 75 L400 110 L360 240 Z" fill="#e6e8fa" opacity=".7"/><circle cx="320" cy="130" r="20" fill="#6879ba"/><path d="M280 200 Q320 150 360 200" fill="#6879ba"/></g><text x="28" y="35" fill="white" font-size="13">MOCK ANIMATIC / SHOT {{ current?.id }}</text></svg><div class="subtitle">{{ current?.text }}</div></div><div class="controls"><ElButton @click="toggle">{{ playing?'暂停':'播放' }}</ElButton><input v-model.number="elapsed" type="range" min="0" :max="total" step="0.1" @input="stopVoice"/><span>{{ elapsed.toFixed(1) }} / {{ total }} 秒</span></div><label><input v-model="narration" type="checkbox" @change="stopVoice"/> 浏览器临时配音（视设备支持）</label><p>构图为程序示意，非 AI 视频。播放仅用于检查字幕与时间线节奏。</p></section></template>
<style scoped>.player{background:#11182b;color:#dce0f0;border-radius:12px;overflow:hidden;margin:20px 0}.screen{position:relative}.screen svg{width:100%;max-height:350px}.subtitle{position:absolute;bottom:20px;text-align:center;width:100%;padding:0 20px;color:white;font-size:18px}.controls{display:flex;align-items:center;gap:12px;padding:16px}.controls input{flex:1}label,p{display:block;font-size:12px;padding:0 16px 12px;color:#a0acc9}</style>
